import csv
import json

expenses = []
with open('csv/expense.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        expenses.append(row)

with open('json/budget.json', 'r') as f:
    budget_data = json.load(f)
    budgets = budget_data['records']

october_meeting_id = 'recggMW2eyCYceNcy'

october_budgets = [b for b in budgets if b['link_to_event'] == october_meeting_id]
print('Budgets for October Meeting:')
for b in october_budgets:
    print(f"  {b['budget_id']}: {b['category']}")

expense_types = {}
for expense in expenses:
    if expense['approved'] == 'true':
        budget_id = expense['link_to_budget']
        for budget in october_budgets:
            if budget['budget_id'] == budget_id:
                category = budget['category']
                cost = float(expense['cost'])
                if category not in expense_types:
                    expense_types[category] = 0
                expense_types[category] += cost
                print(f"Expense: {expense['expense_description']}, Category: {category}, Cost: {cost}")

print('Total by expense type:')
for category, total in expense_types.items():
    print(f"  {category}: {total}")

